const $=id=>document.getElementById(id);
const weekdays=['日','月','火','水','木','金','土'];
export function scheduleLabel(j){const f=j.frequency||'daily';return (f==='weekly'?`毎週${weekdays[j.weekday??1]}曜日`:f==='monthly'?`毎月${j.day||1}日`:f==='halfyear'?`毎年${j.month||1}月・${Number(j.month||1)+6}月 ${j.day||1}日`:'毎日')+' '+j.time}
function cycleFields(){const f=$('sync-frequency').value;$('weekday-field').hidden=f!=='weekly';$('month-field').hidden=f!=='halfyear';$('day-field').hidden=!['monthly','halfyear'].includes(f);if($('month-note'))$('month-note').hidden=!['monthly','halfyear'].includes(f)}
export function scheduleForm(){return `<div class="field" style="margin-top:20px"><div class="row schedule-controls"><div><label for="sync-frequency">実行周期</label><select id="sync-frequency"><option value="daily">毎日</option><option value="weekly">毎週</option><option value="monthly">毎月</option><option value="halfyear">半年ごと</option></select></div><div id="weekday-field" hidden><label for="sync-weekday">曜日</label><select id="sync-weekday">${weekdays.map((d,i)=>`<option value="${i}">${d}曜日</option>`).join('')}</select></div><div id="month-field" hidden><label for="sync-month">実行月</label><select id="sync-month">${Array.from({length:6},(_,i)=>`<option value="${i+1}">${i+1}月・${i+7}月</option>`).join('')}</select></div><div id="day-field" hidden><label for="sync-day">日付</label><select id="sync-day">${Array.from({length:31},(_,i)=>`<option value="${i+1}">${i+1}日</option>`).join('')}</select></div><div class="schedule-time"><label for="sync-time">実行時刻（日本時間・UTC+9）</label><input id="sync-time" type="time" required step="60"></div></div><p id="month-note" class="api-note" hidden>指定日がない月は、その月の末日に実行します。</p></div>`}
export function bindSchedule(schedule,onSave){
$('sync-frequency').value=schedule.frequency;$('sync-time').value=schedule.time;$('sync-weekday').value=schedule.weekday;$('sync-month').value=schedule.month;$('sync-day').value=schedule.day;cycleFields();$('sync-frequency').onchange=cycleFields;
if($('save-global-schedule'))$('save-global-schedule').onclick=()=>{if(!$('sync-time').checkValidity()){$('sync-time').reportValidity();return}onSave({frequency:$('sync-frequency').value,time:$('sync-time').value,weekday:Number($('sync-weekday').value),month:Number($('sync-month').value),day:Number($('sync-day').value)})};
}

export function readSchedule(){return {frequency:$('sync-frequency').value,time:$('sync-time').value,weekday:Number($('sync-weekday').value),month:Number($('sync-month').value),day:Number($('sync-day').value)}}
